// api/_lib/dataset.js is generated by scripts/build.py from data/entries.json, and
// api/dataset.js serves it as a published contract. These tests cover both halves.
//
// The failure mode here is different from registry.js. A stale allowlist rejects a
// click, which someone notices. A stale or misshapen dataset is served with a 200 and a
// cache header, and the first sign of trouble is a downstream consumer quietly working
// from a registry that is missing the last month of entries, or from records that lost a
// field nobody meant to remove. Nothing else in the build checks this: verify-parity.py
// diffs rendered HTML, and check-integrity.py reads committed bytes, so an endpoint that
// drops a field is invisible to both.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { ENTRIES, FIELDS_SERVED, GENERATED } from "./dataset.js";
import handler from "../dataset.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const SOURCE = JSON.parse(fs.readFileSync(path.join(ROOT, "data/entries.json"), "utf8"));

/** Drive the handler the way Vercel does, and collect what it wrote. */
async function call(url = "/api/dataset", method = "GET") {
  const res = {
    statusCode: 0,
    headers: {},
    body: undefined,
    setHeader(k, v) { this.headers[k.toLowerCase()] = v; },
    end(text) { this.body = JSON.parse(text); },
  };
  await handler({ method, url, headers: {} }, res);
  return res;
}

test("every published entry is served", async () => {
  const served = new Set(ENTRIES.map(e => e.id));
  for (const e of SOURCE) {
    assert.ok(served.has(e.id), `${e.id} is published but /api/dataset does not serve it. `
      + "Run python3 scripts/build.py");
  }
  assert.equal(ENTRIES.length, SOURCE.length);
});

test("nothing is served that is not published", () => {
  const published = new Set(SOURCE.map(e => e.id));
  for (const e of ENTRIES) {
    assert.ok(published.has(e.id), `${e.id} is served but not in data/entries.json`);
  }
});

test("the advertised field contract holds for every record", () => {
  // The endpoint names its own fields in the envelope. A record carrying a key that is
  // not in that list means the projection and the contract have drifted apart, which is
  // the whole thing this endpoint exists to prevent.
  const allowed = new Set(FIELDS_SERVED);
  for (const e of ENTRIES) {
    for (const k of Object.keys(e)) {
      assert.ok(allowed.has(k), `${e.id} carries '${k}', which FIELDS_SERVED does not advertise`);
    }
  }
});

test("the fields every entry is required to have are always present", () => {
  // The optional half (year_posed, humans, tags, sources) is deliberately omitted rather
  // than nulled when absent, so it is not checked here. These are the ones a consumer
  // can branch on without a guard.
  for (const e of ENTRIES) {
    for (const k of ["id", "title", "claim", "field", "date", "added", "lab", "model",
                     "verification", "autonomy", "url"]) {
      assert.ok(e[k], `${e.id} is missing '${k}'`);
    }
  }
});

test("values round-trip unchanged from the source data", () => {
  // A projection that quietly reformats a date or truncates a claim would still pass
  // every test above.
  const byId = new Map(SOURCE.map(e => [e.id, e]));
  for (const e of ENTRIES) {
    const src = byId.get(e.id);
    for (const k of ["title", "claim", "field", "date", "added", "lab", "model",
                     "verification", "autonomy", "year_posed"]) {
      if (k in e) assert.deepEqual(e[k], src[k], `${e.id}.${k}`);
    }
    assert.equal(e.url, `https://whataifound.org/finding/${e.id}`);
  }
});

test("the generated block is sorted, so a reordered data file produces no diff", () => {
  const ids = ENTRIES.map(e => e.id);
  assert.deepEqual(ids, [...ids].sort());
});

test("GENERATED is the latest date the data carries, not a build clock", () => {
  const stamps = SOURCE.flatMap(e => [e.added, ...(e.revisions || []).map(r => r.date)])
    .filter(Boolean);
  assert.equal(GENERATED, stamps.sort().at(-1));
});

test("a bare GET returns every entry, newest first, and is cacheable", async () => {
  const res = await call();
  assert.equal(res.statusCode, 200);
  assert.equal(res.body.total, SOURCE.length);
  assert.equal(res.body.entries.length, SOURCE.length);
  assert.equal(res.body.version, 1);
  assert.equal(res.body.generated, GENERATED);

  const dates = res.body.entries.map(e => e.date);
  assert.deepEqual(dates, [...dates].sort().reverse());

  // The one endpoint that overrides the shared no-store. If this regresses, the CDN
  // stops serving it and every consumer hits the function.
  assert.match(res.headers["cache-control"], /public/);
});

test("filters narrow the result and agree with the source data", async () => {
  for (const [q, pass] of [
    ["field=mathematics", e => e.field === "mathematics"],
    ["verification=formal", e => e.verification === "formal"],
    ["autonomy=autonomous", e => e.autonomy === "autonomous"],
    ["lab=OpenAI", e => e.lab === "OpenAI"],
  ]) {
    const res = await call(`/api/dataset?${q}`);
    assert.equal(res.statusCode, 200, q);
    assert.equal(res.body.total, SOURCE.filter(pass).length, q);
    assert.ok(res.body.entries.every(pass), q);
  }
});

test("since filters on added, inclusive of the boundary", async () => {
  const cutoff = [...new Set(SOURCE.map(e => e.added))].sort().at(-1);
  const res = await call(`/api/dataset?since=${cutoff}`);
  assert.equal(res.statusCode, 200);
  assert.equal(res.body.total, SOURCE.filter(e => e.added >= cutoff).length);
  assert.ok(res.body.entries.every(e => e.added >= cutoff));
});

test("filters compose", async () => {
  const res = await call("/api/dataset?field=mathematics&verification=formal");
  assert.equal(res.body.total,
    SOURCE.filter(e => e.field === "mathematics" && e.verification === "formal").length);
});

test("an unknown enum value is a 400 that names what would have worked", async () => {
  for (const q of ["field=maths", "verification=verified", "autonomy=robot"]) {
    const res = await call(`/api/dataset?${q}`);
    assert.equal(res.statusCode, 400, q);
    assert.equal(res.body.error, "bad_request");
    assert.ok(Array.isArray(res.body.accepted) && res.body.accepted.length, q);
  }
});

test("a malformed since is a 400, not a silently empty result", async () => {
  for (const q of ["since=yesterday", "since=2026-8-1", "since=20260801"]) {
    const res = await call(`/api/dataset?${q}`);
    assert.equal(res.statusCode, 400, q);
    assert.equal(res.body.parameter, "since");
  }
});

test("an open vocabulary value that matches nothing is an empty 200, not a 400", async () => {
  // lab and tag gain values without a code change, so there is no allowlist to fail
  // against and "no matches" is a legitimate answer rather than a typo.
  for (const q of ["lab=Nonexistent Institute", "tag=not-a-real-tag"]) {
    const res = await call(`/api/dataset?${q}`);
    assert.equal(res.statusCode, 200, q);
    assert.equal(res.body.total, 0, q);
  }
});

test("limit and offset window the result without changing the total", async () => {
  const all = (await call()).body.entries;
  const res = await call("/api/dataset?limit=5&offset=2");
  assert.equal(res.body.total, all.length);
  assert.equal(res.body.count, 5);
  assert.equal(res.body.offset, 2);
  assert.deepEqual(res.body.entries.map(e => e.id), all.slice(2, 7).map(e => e.id));
});

test("an offset past the end is an empty page, not an error", async () => {
  const res = await call("/api/dataset?offset=100000");
  assert.equal(res.statusCode, 200);
  assert.equal(res.body.entries.length, 0);
  assert.equal(res.body.total, SOURCE.length);
});

test("a nonsense limit or offset is a 400", async () => {
  for (const q of ["limit=-1", "limit=abc", "limit=99999", "offset=-5", "offset=1.5"]) {
    const res = await call(`/api/dataset?${q}`);
    assert.equal(res.statusCode, 400, q);
  }
});

test("a write method is refused with an Allow header", async () => {
  for (const m of ["POST", "PUT", "DELETE", "PATCH"]) {
    const res = await call("/api/dataset", m);
    assert.equal(res.statusCode, 405, m);
    assert.equal(res.headers.allow, "GET, HEAD");
  }
});

test("the served records cannot be mutated by a handler bug", async () => {
  // Object.freeze in the generated file is what stops one request's filtering from
  // leaving a mark on the module every later request reads.
  assert.throws(() => { ENTRIES[0].title = "changed"; }, TypeError);
  assert.throws(() => { ENTRIES.push({}); }, TypeError);
});
